def min_time(n, m, volcanoes):
    dp = [0] * (n + 1)
    reachable = set([(0, 0)])

    for volcano in volcanoes:
        x, y = volcano
        for i in range(n - 1, -1, -1):
            if (x - 1, y - 1) == (0, 0):
                reachable.remove((x - 1, y - 1))
            if (x - 1, y) == (0, y - 1) and (x - 1, y) not in reachable:
                reachable.add((x - 1, y))
            if (x, y - 1) not in reachable:
                reachable.add((x, y - 1))
            for tx in range(1, min(y, n - y) + 1):
                if (x + tx, y + tx) in reachable:
                    dp[y + tx] = min(dp[y + tx], dp[y] + 1)
                    reachable.add((x + tx, y + tx))

    if len(reachable) == 1:
        return dp[len(dp) - 1]

    return -1

