                possible_hosts[(i, j)] += garden_matrix_A[i][j] + garden_matrix_B[i - 1][j]

    # Sort possible hosts and calculate the max reach
    sorted_hosts = sorted(possible_hosts.items(), key=lambda x: x[1], reverse=True)
    for i, (x, _) in enumerate(sorted_hosts):
        if best_reach + possible_hosts[x] > N * M:
            break
        best_reach += possible_hosts[x]

    # Calculate max reach on left if right-postioned is not full
    if possible_hosts.get((N, M), 0) == N * M:
        for i in range(1, M):
            if possible_hosts[(N, i)] == 0:
                best_reach += possible_hosts[(N, i - 1)]
