def find_path(parent, node, destination):
    if parent[node] == destination:
        return 1
    if parent[node] == -999:
        return 0
    return find_path(parent, parent[node], destination)

def tree_extremality(N, nums, edges):
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)
    path_lengths = {v: find_path(graph, v - 1, 0) for v in range(1, N + 1)}
    parent = [-999] * (N + 1)
    size = [0] * (N + 1)
    def solve(start):
        nonlocal parent
        parent[start] = parent[start - 1]
        for child in graph[start]:
            if child != parent[start]:
                parent[child] = start
                solve(child)
    solve(1)
    mst = sorted([(v, size[v]) for v in range(1, N + 1)], key=lambda x: x[1])
    mst = mst[:-1]
    num_rejected = 0
    total_cost = 0
    for u, size_u in mst:
        if size_u == 0:
            continue
        if size_u >= 3:
            break
        if size_u == 1:
            num_rejected += 1
        else:
            size_u = 2
        for v in graph[u]:
            if v != parent[u]:
                total_cost += size_u
    weighted_path = sum([x * path_lengths[u] for u, x in mst if x == 1])
    return weighted_cost // (weighted_path + num_rejected)

