from collections import defaultdict

def min_unattractiveness(N, markers, edges):
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    def dfs(current, parent, markers_used):
        if current in markers_used:
            return float('inf')

        if current == 1:
            return 0

        min_unattractiveness = float('inf')
        for neighbor in graph[current]:
            if neighbor != parent:
                min_distance = dfs(neighbor, current, markers_used)
                unattractiveness = min(abs(markers_used[current] - markers_used[neighbor]) + min_distance,
                                       abs(markers_used[current] - markers_used[neighbor]) - min_distance)

                min_unattractiveness = min(min_unattractiveness, unattractiveness)

        return min(min_unattractiveness, dfs(neighbor, current, markers_used) + 1 if neighbor != 1 else float('inf'))

    return dfs(1, -1, markers[:-1])

