def find_modulo(K, P, N, s):
    gcd_value = gcd(K, P)
    M = N // gcd(gcd_value, P)
    return backtrack(K, P, N, M, tuple(s), set(), set())

def backtrack(K, P, N, M, s, seen, memo):
