        return 0
    key = frozenset((K, *s[:N]))
    return (s[-N:] - s[:-N] - (M-1) * K) % K + (s[-N:] - s[:-N] - (M-1) * (P - seen[k] % P)) % (P - seen[k]%P) * gcd(K, P) + (seen[k] + gcd(K, P) - P) * P for k in range(N) if k not in memo or memo[k] > k)

