def min_travel_time(n, m, volcanoes):
    if n < m or n < len(volcanoes) or m != len(volcanoes):
        return -1

    for x, y in volcanoes:
        if x == 1 and y == 1:
            continue  # Don't count the first cell as a volcano

        for i in range(1, x):
            if i != y:
                return -1

        for j in range(1, y):
            if j != x:
                return -1

    mountains = len(volcanoes)
    steps_needed = [0] * mountains

    for i, (x, y) in enumerate(volcanoes, start=1):
        steps_needed[i] = y + 1  # Add mountain to previous cell's steps

    unblocked_factors = {x}
    for i in range(2, photons[n//2] + 1, 2):
        unblocked_factors.add(i)
        unblocked_factors.add(n // 2 - i + 1)

    previous, current = 2, 1
    while previous <= n + 1:
        for factor in unblocked_factors:
            prev = previous
            current = previous // factor
            while current > 0 and current in previous:
                steps_needed[previous] += 1
                p, q = divmod(index, factor)
                if q:
                    weight = index // steps_needed[p] % 2 != q % 2
                else:
                    weight = prev // steps_needed[p]
                if steps_needed[q] < steps_needed[p] * factor or weight:
                    steps_needed[q] += steps_needed[p] * factor
                    index, previous = q, p
                    break  
        unblocked_factors = min(unblocked_factors - set(common % factor for factor in unblocked_factors))
        index += 1
        previous *= 2
        if step > n + 1:
            break
        steps_needed[index] += step

    return n-sum(steps_needed[:-1])

