from math import factorial

def binomial_coefficient(n, k):
    coeff = factorial(n) // (factorial(k) * factorial(n - k))
    return coeff

def expected_colorfulness(n, k, blocks):
    sums = {i: 0 for i in range(201)}

    for _ in range(n):
        (a, c) = blocks.pop(0)
        if a in sums:
            sums[a] += 1
        else:
            sums[a] = 1

    top = 0
    for sum_count in sums.values():
        if sum_count > 1:
            top += binomial_coefficient(n, sum_count) * (sum_count - 1)

    bottom = factorial(n) // (factorial(k) * factorial(n - k)) + top

    return 1 if bottom == 0 else 1 - top / bottom

