import sys

def find_max_students(N, M, A, B):
    max_students_left = 0
    max_students_top = 0
    for row in range(N):
        if row % 2 == 0:
            # Left edge hostel has priority over top edge
            if max_students_left < sum(A[row]):
                max_students_left = sum(A[row])
            if max_students_top < sum(B[row]):
                max_students_top = sum(B[row])
        else:
            # Top edge hostel has priority over left edge
            if max_students_top < sum(B[row]):
                max_students_top = sum(B[row])
            if max_students_left < sum(A[row]):
                max_students_left = sum(A[row])
    return max(max_students_top, max_students_left)

