            return i, len(s) - 1
    return -1, -1

def solve(s, b):
    """Solve the problem for the given s and b."""
    n = len(s)
    for i, a in enumerate(s):
        if a != b[0]:
            break
    else:
        return 0, len(s) - 1
    j, _ = find_i_j(s, b)
    if j == -1:
        return -1, -1
    i = max(i + 1, max(j, find_i_j(s[a:], b)[-1] + 1)[0] + 1)
    return i, j

