import math
from collections import defaultdict

def fibonacci_k(k, N, *s):
    # Check if the sequence is cyclic
    is_cyclic = False
    for n in range(N - 1, N - 1000):
        if s[n] == s[n + 1]:
            is_cyclic = True
            break

    def extended_gcd(a, b):
        if a == 0:
            return (b, 0, 1)
        gcd, x, y = extended_gcd(b % a, a)
        return (gcd, y - (b // a) * x, x)

    def mod_inv(a, m):
        gcd, x, y = extended_gcd(a, m)
        if gcd != 1:
            raise ValueError("Modular inverse does not exist")
        return x % m

    def mod_exp(a, n, m):
        result = 1
        a = a % m
        while n > 0:
            if n % 2 == 1:
                result = (result * a) % m
            n = n >> 1
            a = (a * a) % m
        return result

    def fibonacci_recursive(n):
        a, b = 0, 1
        for _ in range(n):
            a, b = b, (a + b) % k
        for i in range(n - 1):
            a, b = (b - s[i]) % k, (a - s[i + 1]) % k
        return a

    if is_cyclic:
        return fibonacci_recursive(N - 1)
    else:
        intersect = set()
        for j in range(max(0, N - (k-1)), N-1):
            for v in s:
                if v == s[j % N]:
                    intersect.add(j)
                    break
        intersect -= set(range(len(s)))
        expected = {j if j not in intersect or i % k == 0 else s[i % N] % k for i, j, v in enumerate(range(min(N-1, k-1), N)) if v == s[j % N]}
        return mod_inv(sum(1 for _ in expected) % k, k) % k

