from collections import defaultdict

def lcm(x, y):
    return x * y // gcd(x, y)

def gcd(x, y):
    if y == 0:
        return x
    else:
        return gcd(y, x % y)

def find_value(sum_k, k_limit, queue, memo):
    if memo[k_limit][sum_k] != None:
        return memo[k_limit][sum_k]
    for neighbor in range(k_limit + 1, sum_k + 1):
        queue[neighbor - k_limit] = neighbor
    queue.sort()
    for i in range(1, 1 << queue[k_limit], 2):
        s = sum_k
        for j in range(k_limit + 1):
            if i & (1 << j):
                s = s + queue[j] - sum_k
        memo[k_limit][sum_k] = s
        if sum(s) <= sum_k:
            find_value(s, k_limit, queue, memo)
        memo[k_limit][sum_k] = None

def solution(n, k, s, m, values):
    max_cycle = s[n-1]
    total = 0
    for value in values:
        total += value
    if max(max_cycle, total) > n:
        return 1
    while sum(range(n-n // max_cycle)) <= m - k:
        k = k + int(sum(range(n-n // max_cycle)) - k)
        first = k - n - 1
        first_sum = sum(range(n-n // max_cycle))
        for i in range(k, k + n):
            if not first_sum + i + 1 <= m - k:
                break
            first_sum += i + 1
        if first_sum < m - k:
            first_sum += n
        total = total - first_sum
        total = total + n
        queue = [k] * n
        queue.sort()
        memo = [[None] * (1000000 + 1) for _ in range(n)]
        find_value(0, k, queue, memo)
        quick = 1
        for i in range(n):
            quick *= 1 + memo[i][quick]
        if quick == 1:
            return 0
        else:
            sum_k = n
            k_limit = 0
            for j in range(n):
                if memo[j][0] != None:
                    k_limit = j
                    break
            k_limit += first - 1
            quick = quick * lcm(first_sum, n)
            for i in range(first):
                quick = quick * (k - first + i + 1)
            fast, q = divmod(k, n)
            for i in range(fast + 1):
                quick = quick * q + first - 1
            results = sum(range(m - k + 1, m + quick, quick))
            values.append(results)
    return value

