import sys

Edge = namedtuple("Edge", ['origin', 'destination'])
def path_to_vertex(path, dictionary):
    if path[-1].destination not in dictionary:
        return -1
    stack = [path[-1]]
    nextindexmap = {}
    indexmap = {v: i for i, v in enumerate(dictionary[path[-1].destination])}

    while len(stack) != 0:
        vertex = stack.pop()
        rimap = nextindexmap.get(vertex)
        if rimap is not None:
            stack.append(vertex for _ in range(len(vertex.origin) - rimap))
            nextindexmap[vertex] = nextindexmap.get(vertex) - 1
        index = indexmap[vertex.destinaion]
        nextindexmap.update({vertex.origin[index]: index + 1})
        nextindexmap.setdefault(vertex.source[index], index + 1)

    return nextindexmap

def main():
    n, m = map(int, input().split())
    queue = deque()
    parents = [-1] * n

