        current = dequeue()
        for e in current.target:
            if parents[e.destination] >= 0:
                continue
            parents[e.destination] = e.origin
            neighbors = -1
            for neighbor in city_map[e.destination]:
                if neighbors < 0:
                    neighbors = path_to_vertex([e.destination], city_map)
