import heapq

def find_xor_dominating_set(graph):
    n = len(graph)
    parent, rank = [i for i in range(n)], [1] * n
    sets = 1

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        rootX, rootY = find(x), find(y)
        if rootX == rootY:
            return False
        if rank[rootX] > rank[rootY]:
            rootX, rootY = rootY, rootX
        parent[rootX] = rootY
        rank[rootY] += rootX != rootY
        if rank[rootX] == rank[rootY]: 
            sets -= 1
        return True

    # Construct the set-cover problem
    mat = [0] * (n * n)
    for i in range(n):
        for j in range(n):
            if i != j:
                mat[graph[i] * n + graph[j]] = 1

    # Disperse the matrix
    for i in range(n * n):
        if i % n == n - 1:
            heapq.heappush(element_idx, (mat[i], i))
    times = 0
    while times < n:
        val, col_idx = heapq.heappop(element_idx)
        row_idx = col_idx // n
        if union(row_idx, col_idx % n * n):
            times += 1

    # Recover the set of solutions
    dominators = {}
    dominator_list = []
    for parent_idx in range(n * n):
        current = parent[parent_idx]
        while current != parent_idx:
            dominator_list.append(current)
            parent_idx = parent[current]
        dominator_list.append(current)
        if dominator_list[0] != parent_idx:
            replicates = set()
            while dominator_list[-1] != dominator_list[0]:
                replicates.add(dominator_list.pop())
            dominators[parent_idx] = dominator_list + sorted(list([0] + replicates))

    dominator_val = {index: dominators[index] for index in range(len(dominators))}
    output = []

    while dominator_list:
        dominant = dominator_val[dominator_list.pop(0)]
        output.extend(dominant)

    return output

