    occurrences = []

    while i <= n - m:
        match = True
        for j in range(m):
            if text[i + j] != pattern[j]:
                match = False
                break
        if match:
            occurrences.append(i)
        i += 1
    return occurrences

def evaluate_expression(text, start, end):
    subtext = text[start:end]
    reversed_subtext = reverse_string(subtext)
    rest_end = len(text) - 1 if (end < len(text) - 1 or end == len(text)) else len(text)
    left_side = text[start + 1 : end].strip()
    right_side = text[:end - 1].strip()
    return int(text[start]) + int(left_side) * int(reversed_subtext[-1]) + int(right_side) * int(reversed_subtext[0])

def solve_problem(a, b):
    a = a.lower()
    b = b.lower()
    occurrences = find_letters(b, a)

    for i in occurrences:
        if b:
            if i <= len(b):
                if evaluate_expression(a, i, i + len(b) - 1) == eval(b):
                    return i, i + len(b) - 1
    return -1, -1

a = input().strip()
b = input().strip()
i, j = solve_problem(a, b)
print(str(i) + " " + str(j))
